#include "app.h"
#include "main.h"

#include <stdio.h>
#include <stdint.h>
#include <string.h>

/* Handles generated by CubeMX */
extern ADC_HandleTypeDef hadc1;
extern UART_HandleTypeDef huart2;

/* ADC configuration */
#define ADC_BUFFER_SIZE     4U
#define ADC_MAX_VALUE       4095U
#define ADC_REFERENCE_MV    3300U

/* UART configuration */
#define UART_BUFFER_SIZE    64U

/* Measurement interval */
#define MEASUREMENT_INTERVAL_MS 500U

/* DMA buffers */
static uint16_t adc_buffer[ADC_BUFFER_SIZE];
static char uart_buffer[UART_BUFFER_SIZE];

/* Shared variables */
static volatile uint16_t adc_value = 0U;
static volatile uint8_t adc_data_ready = 0U;
static volatile uint8_t uart_tx_busy = 0U;

/* Timing */
static uint32_t last_transmission_time = 0U;


/* ADC DMA completion callback */
void HAL_ADC_ConvCpltCallback(ADC_HandleTypeDef *hadc)
{
    if (hadc->Instance == ADC1)
    {
        uint32_t adc_sum = 0U;

        for (uint32_t i = 0U; i < ADC_BUFFER_SIZE; i++)
        {
            adc_sum += adc_buffer[i];
        }

        adc_value = (uint16_t)(adc_sum / ADC_BUFFER_SIZE);
        adc_data_ready = 1U;
    }
}


/* UART DMA transmission complete callback */
void HAL_UART_TxCpltCallback(UART_HandleTypeDef *huart)
{
    if (huart->Instance == USART2)
    {
        uart_tx_busy = 0U;
    }
}


/* Application initialization */
void setup(void)
{
    const char *message = "\r\nADC + DMA + UART application started\r\n";

    adc_value = 0U;
    adc_data_ready = 0U;
    uart_tx_busy = 0U;

    last_transmission_time = HAL_GetTick();

    /* Start UART message using blocking transmission */
    HAL_UART_Transmit(
        &huart2,
        (uint8_t *)message,
        (uint16_t)strlen(message),
        HAL_MAX_DELAY
    );

    /* Start ADC with DMA in circular mode */
    if (HAL_ADC_Start_DMA(
            &hadc1,
            (uint32_t *)adc_buffer,
            ADC_BUFFER_SIZE) != HAL_OK)
    {
        const char *error_message = "ERROR: ADC DMA start failed\r\n";

        HAL_UART_Transmit(
            &huart2,
            (uint8_t *)error_message,
            (uint16_t)strlen(error_message),
            HAL_MAX_DELAY
        );

        Error_Handler();
    }

    const char *success_message = "ADC DMA started successfully\r\n";

    HAL_UART_Transmit(
        &huart2,
        (uint8_t *)success_message,
        (uint16_t)strlen(success_message),
        HAL_MAX_DELAY
    );
}


/* Main application loop */
void loop(void)
{
    uint16_t current_adc;
    uint32_t voltage_mv;
    uint32_t current_time;

    current_time = HAL_GetTick();

    /* Check measurement availability and transmission interval */
    if ((adc_data_ready != 0U) &&
        (uart_tx_busy == 0U) &&
        ((current_time - last_transmission_time) >=
         MEASUREMENT_INTERVAL_MS))
    {
        /*
         * Temporarily disable interrupts while copying shared data.
         */
        __disable_irq();

        current_adc = adc_value;
        adc_data_ready = 0U;

        __enable_irq();

        /* Convert ADC value to millivolts */
        voltage_mv =
            ((uint32_t)current_adc * ADC_REFERENCE_MV)
            / ADC_MAX_VALUE;

        /* Format the output without floating-point arithmetic */
        int length = snprintf(
            uart_buffer,
            sizeof(uart_buffer),
            "ADC: %u | Voltage: %lu.%03lu V\r\n",
            (unsigned int)current_adc,
            (unsigned long)(voltage_mv / 1000U),
            (unsigned long)(voltage_mv % 1000U)
        );

        if ((length > 0) &&
            ((size_t)length < sizeof(uart_buffer)))
        {
            uart_tx_busy = 1U;

            if (HAL_UART_Transmit_DMA(
                    &huart2,
                    (uint8_t *)uart_buffer,
                    (uint16_t)length) != HAL_OK)
            {
                uart_tx_busy = 0U;
            }
            else
            {
                last_transmission_time = current_time;
            }
        }
    }
}
